function renderCards(){const box=$('#toolContent'),c=currentCards[cardIndex];if(!c){box.innerHTML='<p>No flashcards remain in this set.</p><button class="primary" id="newFlashcardSet" type="button">Create a fresh set</button>';$('#newFlashcardSet').onclick=()=>createTool('cards',currentCardSource,currentCardTitle,toolReturnPage);return}const practice=cardPracticeMarkup(c,'topic');box.innerHTML=`<p class="eyebrow">LUMI · FLASHCARDS</p><h1>Review with flashcards</h1><p>Card ${cardIndex+1} of ${currentCards.length}. Type an answer or choose from shuffled options.</p><div class="flash-card"><b>QUESTION</b><p>${esc(c.front)}</p>${practice.markup}</div><div class="tool-controls"><button class="secondary" id="prevCard" type="button">← Previous</button><button class="secondary" id="nextCard" type="button">Next →</button><button class="secondary" id="shuffleCards" type="button">Randomize cards</button><button class="secondary" id="editCard" type="button">Edit card</button><button class="text-button" id="deleteCard" type="button">Remove card</button><button class="primary" id="newFlashcardSet" type="button">Create a fresh set</button></div>`;bindCardPractice(box,c,'topic',practice.choices,renderCards);$('#prevCard').onclick=()=>{cardIndex=(cardIndex-1+currentCards.length)%currentCards.length;renderCards()};$('#nextCard').onclick=()=>{cardIndex=(cardIndex+1)%currentCards.length;renderCards()};$('#shuffleCards').onclick=()=>{currentCards=shuffleFlashcards(currentCards);cardIndex=0;renderCards()};$('#deleteCard').onclick=()=>{currentCards.splice(cardIndex,1);cardIndex=Math.max(0,cardIndex-1);renderCards()};$('#editCard').onclick=()=>{const front=prompt('Edit question or term:',c.front);if(front===null)return;const back=prompt('Edit answer or explanation:',c.back);if(back!==null){c.front=front;c.back=back;renderCards()}};$('#newFlashcardSet').onclick=()=>createTool('cards',currentCardSource,currentCardTitle,toolReturnPage)}
