$('#fileInput').addEventListener('change',async e=>{
  const file=e.target.files[0];if(!file)return;
  currentTopic=null;currentMaterial='';uploadedText='';currentCards=[];currentBundle=null;currentBundleQuiz=[];currentMaterialId='';currentFile=file.name;
  currentDeckTitle=file.name.replace(/[.][^.]+$/,'');currentKnownCards=[];$('#deckTitle').value=currentDeckTitle;
  $('#makeReviewer').dataset.generated='false';$('#makeReviewer').textContent='Create full study bundle';
  $('#fileActions').hidden=true;$('#reviewerOutput').hidden=true;$('#flashcardOutput').hidden=true;$('#plainLanguageOutput').hidden=true;$('#gapOutput').hidden=true;$('#bundleQuizOutput').hidden=true;$('#sourceMaterialOutput').hidden=true;
  $('#fileStatus').textContent='Extracting text from your file…';
  try{
    const response=await fetch('/api/extract?name='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});
    const extracted=await response.json().catch(()=>({error:'The file is larger than the current hosting capacity or could not be processed.'}));
    if(!response.ok)throw Error(extracted.error||'File extraction failed.');
    uploadedText=extracted.text;currentMaterial=uploadedText;
    persistCurrentMaterial().then(()=>{$('#fileStatus').textContent='Upload and extracted text saved on this device. Name your deck, choose a flashcard count, and create the Lumi study set.'}).catch(()=>{$('#fileStatus').textContent='Text extracted, but this browser could not save a copy. Choose a flashcard count to continue.'});
    $('#fileActions').hidden=false;$('#fileStatus').textContent='Text extracted from '+file.name+'. Name your deck, choose a flashcard count, and create the study set.';
  }catch(error){currentMaterial='';$('#fileStatus').textContent=error.message.includes('fetch')?'File processing could not reach the LearnIT server. Please try again.':error.message}
});
