function setMobileNavOpen(open){const toggle=$('#mobileMenuToggle'),backdrop=$('#mobileNavBackdrop'),wasOpen=document.body.classList.contains('mobile-nav-open'),mobile=window.matchMedia('(max-width: 900px)').matches;if(!toggle||!backdrop)return;const shouldOpen=Boolean(open&&mobile);document.body.classList.toggle('mobile-nav-open',shouldOpen);toggle.setAttribute('aria-expanded',String(shouldOpen));toggle.setAttribute('aria-label',shouldOpen?'Close navigation menu':'Open navigation menu');backdrop.hidden=!shouldOpen;if(shouldOpen)$('#mobileNavClose').focus();else if(wasOpen&&mobile)toggle.focus({preventScroll:true})}
$('#mobileMenuToggle').addEventListener('click',()=>setMobileNavOpen(!document.body.classList.contains('mobile-nav-open')));
